import{_ as e,o as a,c as t,a4 as s}from"./chunks/framework.B-wJupoK.js";const r="/assets/image-20260207194637350.CcSJZ3I7.png",o="/assets/image-20260207194717193.BLDjX9Cj.png",l="/assets/image-20260207200203851.DBptIesN.png",i="/assets/image-20260207200326112.fwARJleH.png",p="/assets/image-20260207213037686.RbKLKMw7.png",c="/assets/image-20260207213121115.CR0wprZh.png",g="/assets/image-20260207213145206.Gi2OFaYU.png",m="/assets/image-20260207222939933.glghKE6v.png",h="/assets/image-20260207224757303.CILKBdNM.png",q=JSON.parse('{"title":"端云一体 一天重新开发的元服务-奇趣故事匣经验分享","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/端云一体 一天重新开发的元服务-奇趣故事匣经验分享/端云一体 一天重新开发的元服务-奇趣故事匣经验分享.md","filePath":"鸿蒙开发技巧/端云一体 一天重新开发的元服务-奇趣故事匣经验分享/端云一体 一天重新开发的元服务-奇趣故事匣经验分享.md","lastUpdated":1770481109000,"__rawMarkdown":"# 端云一体 一天重新开发的元服务-奇趣故事匣经验分享\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：[https://blog.zbztb.cn/](https://blog.zbztb.cn/)\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\n学习技术最好的做法就是应用技术，带着这个目标。\\n\\n我这次打算深度使用华为-鸿蒙的端云一体，做一个完整的作品 **奇趣故事匣**。\\n\\n先看成果。\\n\\n![](assets/image-20260207194637350.png)\\n\\n---\\n\\n![](assets/image-20260207194717193.png)\\n\\n\\n\\n\\n\\n奇趣故事匣其实在25年的时候就已经上架了成了一个元服务\\n\\n那时候的是传统架构\\n\\n1. java后端\\n2. 鸿蒙前端\\n\\n因为是传统后端开发的方式，所以需要一定的后端能力:\\n\\n1. 后端编程语言\\n2. 服务器-域名-运维等\\n\\n这个过程还是很耗人的，尤其对于一个初学者来说。\\n\\n\\n\\n## 端云一体的优势\\n\\n云开发（Serverless）是一种由云端平台提供服务器和环境、让开发者只需关注业务逻辑的按需服务架构，具备零运维、弹性伸缩、安全可靠等优势，并支持端云一体化开发。\\n\\n![](assets/image-20260207200203851.png)\\n\\n总的来说，开发者只需要在两个窗口内基本就可以完成整个应用的开发。\\n\\n\\n\\n## 环境一览\\n\\n1. **AGC平台-管理云端资源**\\n2. **DevEco Studio 实现全链路开发**\\n\\n---\\n\\n![](assets/image-20260207200326112.png)\\n\\n![](assets/image-20260207213037686.png)\\n\\n---\\n\\n其中关于云端的调试，DevEco Studio中也提供了调试面板\\n\\n![](assets/image-20260207213121115.png)\\n\\n![](assets/image-20260207213145206.png)\\n\\n## 端云一体的概念详解\\n\\n认证服务：助力应用快速构建安全可靠的用户认证系统。\\n云函数： 提供Serverless化的代码开发与运行平台。\\n云数据库：提供端云数据的协同管理。\\n云缓存：为云函数提供Key-Value型高速缓存。\\n云存储：助力应用存储图片、音频、视频等内容，并提供高品质的上传、下载、分享能力。\\n云监控：提供云开发服务的运行指标、日志和告警，助力实时洞察服务运行状态。\\nAPI网关：一个API开放平台，支持对多种API源的全生命周期管理。\\n云托管：提供网站的托管和静态CDN加速。\\n云应用引擎：提供包括部署、运行、运维在内的一站式应用托管方案。\\n\\n---\\n\\n其中最基本的**云函数**、**云数据库**、**云存储**足够支撑起一个差不多的应用了。\\n\\n\\n\\n## 经验分享\\n\\n\\n\\n过程中确实还是少不了一些问题\\n\\n1. 端云一体的环境，但是数据库、数据表以及它们的关联，其实都需要自己先去设计。\\n2. 那另外比如我们所做的这个故事类的应用，它有一些故事，然后一些图片，可能还包括一些视频等等，这些素材其实也需要自己去设计的。\\n3. 过程当中还有不少是关于一些权限的问题，就是你怎么样把本地设计好的一些数据表同步到这个AGC平台上。\\n4. 如果是应用内用户产生的数据，它又是否有什么权限，然后可以同步上去，这一块其实都要踩一些坑\\n5. 最后再说一些场面话，我们学技术其实最好的方式就是做一些产品，这个踩坑其实是必然的。过后呢，我们相信再做第二个第三个应用之前的一些坑就会变成我们实际的开发经验了。\\n\\n\\n\\n\\n\\n## 开发过程中的技术分享\\n\\n25年、26年已经有苗头都在宣传 **一个人公司**，所以作为独立的个体只要是关于提高生产力的，可能都需要了解包括使用。\\n\\n这里分享一下我的开发 配套技术：\\n\\n1. 使用了海外版本的Trae+Gemini3-Pro完成目前功能的开发\\n2. 使用了智能体、skill、rule、mcp等主流AI技术\\n3. 使用了HarmonyOS自动构建脚本\\n4. 使用的是元服务+V2状态管理+Navigation\\n5. 使用了AI脚本批量生产素材\\n\\n![](assets/image-20260207222939933.png)\\n\\n\\n\\n## 这会的成功\\n\\n此时的时间是**2026年2月7日22:35:25**，边聊天的时候我也给这个应用接入了用户系统了。\\n\\n![](assets/image-20260207224757303.png)\\n\\n## 总结\\n\\n1. AI时代，要学会工具来提效\\n2. 鸿蒙的端云使用很方便，值得一试\\n\\n## 参考链接\\n\\n1. 端云一体\\n\\n   > https://developer.huawei.com/consumer/cn/doc/AppGallery-connect-Guides/agc-serverless-overview-0000001509965245\\n\\n2. 端云一体教程\\n\\n   > https://blog.zbztb.cn/%E9%B8%BF%E8%92%99%E5%BC%80%E5%8F%91%E6%8A%80%E5%B7%A7/HarmonyOSNext%20%E7%AB%AF%E4%BA%91%E4%B8%80%E4%BD%93%E5%8C%96/HarmonyOSNext%20%E7%AB%AF%E4%BA%91%E4%B8%80%E4%BD%93%E5%8C%96%E5%AE%8C%E6%95%B4%E7%89%88/HarmonyOSNext%20%E7%AB%AF%E4%BA%91%E4%B8%80%E4%BD%93%E5%8C%96%E5%AE%8C%E6%95%B4%E7%89%88.html\\n\\n**关注我**，持续分享**鸿蒙开发** + `AI` 提效的实战技巧。\\n\\n<!-- ![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg) -->"}'),E={name:"鸿蒙开发技巧/端云一体 一天重新开发的元服务-奇趣故事匣经验分享/端云一体 一天重新开发的元服务-奇趣故事匣经验分享.md"};function _(d,n,A,b,u,B){return a(),t("div",null,[...n[0]||(n[0]=[s("",48)])])}const C=e(E,[["render",_]]);export{q as __pageData,C as default};
